            removed_zero = true;
            continue;
        }
        final_s += s_prime[i];
    }

    if (!removed_zero) {
        final_s = "";
        for (char c : s_prime) {
            if (c == '0' && !removed_zero) {
                removed_zero = true;
                continue;
