class Solution {
    public int[] validSequence(String word1, String word2) {

        int n = word1.length();
        int m = word2.length();

        int[] last = new int[m];

        int j = m - 1;

        // Find the positions for matching word2 from the end
        for (int i = n - 1; i >= 0; i--) {
            if (j >= 0 && word1.charAt(i) == word2.charAt(j)) {
                last[j] = i;
                j--;
            }
        }

        int[] ans = new int[m];

        j = 0;
        int usedMismatch = 0;

        // Build the lexicographically smallest sequence
        for (int i = 0; i < n && j < m; i++) {

            // Exact match
            if (word1.charAt(i) == word2.charAt(j)) {
                ans[j] = i;
                j++;
            }

            // Use the one allowed mismatch
            else if (usedMismatch == 0 &&
                    (j == m - 1 || i + 1 <= last[j + 1])) {

                ans[j] = i;
                j++;
                usedMismatch = 1;
            }
        }

        if (j != m) {
            return new int[0];
        }

        return ans;
    }
}

leetcode:maximum-area-of-two-non-overlap.code:
class Solution:
    def maxArea(self, mat: List[List[int]]) -> int:
        if not mat or not mat[0]:
            return 0
        x = mat
        m=len(mat)
        n=len(mat[0])
        dp=[[0] * n for _ in range(m)]
        mp = min(m,n)
        g = [[] for _ in range(mp + 1)]
        for i in range(m):
            for j in range(n):
                if mat[i][j] == 1:
                    if i == 0 or j == 0:
                        dp[i][j] = 1
                    else:
                        dp[i][j] = min(dp[i-1][j],dp[i][j-1],dp[i-1][j-1]) + 1
                    g[dp[i][j]].append((i,j))
        minr = float('inf')
        maxr = float('-inf')
        minc = float('inf')
        maxc = float('-inf')
        for k in range(mp, 0, -1):
            for r,c in g[k]:
                if r<minr : minr = r
                if r>maxr : maxr = r
                if c<minc : minc = c
                if c>maxc : maxc = c
            if maxr - minr >= k or maxc -minc >= k:
                return k*k
        return 0

